package com.rpgtemplate.core.production;
import java.util.*;import com.google.gson.*;import java.nio.charset.StandardCharsets;
/** Resource-driven client pose curves, independent of Minecraft and damage calculation. */
public final class BuildMotion {
 public static final int CHANNELS=22;public record Frame(float tick,float[] pose){}public record Clip(int id,int duration,int poseDuration,int hitTick,List<Frame> frames){}
 public static final Map<Integer,Clip> CLIPS;
 static {try(var in=BuildMotion.class.getResourceAsStream("/data/rpgtemplate/production/build_motion.json")){Map<Integer,Clip> clips=new LinkedHashMap<>();for(var raw:JsonParser.parseReader(new java.io.InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonArray()){var j=raw.getAsJsonObject();List<Frame> frames=new ArrayList<>();float last=-1;for(var f:j.getAsJsonArray("frames")){var a=f.getAsJsonObject();float tick=a.get("tick").getAsFloat();if(tick<=last)throw new IllegalArgumentException("unordered motion");last=tick;var array=a.getAsJsonArray("pose");if(array.size()!=CHANNELS)throw new IllegalArgumentException("pose size");float[] v=new float[CHANNELS];for(int i=0;i<v.length;i++){v[i]=array.get(i).getAsFloat();if(!Float.isFinite(v[i]))throw new IllegalArgumentException("nonfinite pose");}frames.add(new Frame(tick,v));}var c=new Clip(j.get("id").getAsInt(),j.get("duration").getAsInt(),j.get("pose_duration").getAsInt(),j.get("hit_tick").getAsInt(),List.copyOf(frames));if(c.duration()<1||c.duration()>200||c.poseDuration()>c.duration()||frames.size()<2||frames.get(0).tick()!=0||last!=c.poseDuration()||clips.put(c.id(),c)!=null)throw new IllegalArgumentException("invalid clip");}CLIPS=Map.copyOf(clips);}catch(Exception ex){throw new ExceptionInInitializerError(ex);}}
 public static float ease(float t){t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);}
 public static float[] sample(int id,float age){float[] out=new float[CHANNELS];var clip=CLIPS.get(id);if(clip==null||!Float.isFinite(age)||age<=0||age>=clip.poseDuration())return out;var frames=clip.frames();int lo=1,hi=frames.size()-1,found=-1;while(lo<=hi){int mid=(lo+hi)>>>1;if(frames.get(mid).tick()>=age){found=mid;hi=mid-1;}else lo=mid+1;}if(found<0)return out;var a=frames.get(found-1);var b=frames.get(found);float t=ease((age-a.tick())/(b.tick()-a.tick()));for(int k=0;k<CHANNELS;k++)out[k]=a.pose()[k]+(b.pose()[k]-a.pose()[k])*t;return out;}
 public static boolean valid(int id,int duration,double...coordinates){var c=CLIPS.get(id);if(c==null||duration!=c.duration())return false;for(double x:coordinates)if(!Double.isFinite(x)||Math.abs(x)>30000000)return false;return true;}
}
